package com.cleanroute.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="saved_route",indexes=@Index(name="ix_saved_route_user_created",columnList="user_id, created_at"))
public class SavedRoute {
 @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="origin_name",nullable=false,length=200) private String originName; @Column(name="origin_latitude",nullable=false) private double originLatitude; @Column(name="origin_longitude",nullable=false) private double originLongitude; @Column(name="destination_name",nullable=false,length=200) private String destinationName; @Column(name="destination_latitude",nullable=false) private double destinationLatitude; @Column(name="destination_longitude",nullable=false) private double destinationLongitude; @Column(name="geometry_polyline",columnDefinition="text") private String geometryPolyline; @Enumerated(EnumType.STRING) @Column(name="travel_mode",nullable=false,length=16) private TravelMode travelMode; @Enumerated(EnumType.STRING) @Column(name="route_preference",nullable=false,length=16) private RoutePreference routePreference; @Column(name="pollution_score") private Double pollutionScore; @Column(name="estimated_travel_time_seconds") private Integer estimatedTravelTimeSeconds; @Column(name="distance_meters") private Double distanceMeters; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 protected SavedRoute(){} public SavedRoute(UUID user,String on,double ola,double olo,String dn,double dla,double dlo,String geometry,TravelMode mode,RoutePreference pref,Double score,Integer duration,Double distance){id=UUID.randomUUID();userId=user;originName=on;originLatitude=ola;originLongitude=olo;destinationName=dn;destinationLatitude=dla;destinationLongitude=dlo;geometryPolyline=geometry;travelMode=mode;routePreference=pref;pollutionScore=score;estimatedTravelTimeSeconds=duration;distanceMeters=distance;createdAt=Instant.now();}
 public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getOriginName(){return originName;} public double getOriginLatitude(){return originLatitude;} public double getOriginLongitude(){return originLongitude;} public String getDestinationName(){return destinationName;} public double getDestinationLatitude(){return destinationLatitude;} public double getDestinationLongitude(){return destinationLongitude;} public String getGeometryPolyline(){return geometryPolyline;} public TravelMode getTravelMode(){return travelMode;} public RoutePreference getRoutePreference(){return routePreference;} public Double getPollutionScore(){return pollutionScore;} public Integer getEstimatedTravelTimeSeconds(){return estimatedTravelTimeSeconds;} public Double getDistanceMeters(){return distanceMeters;} public Instant getCreatedAt(){return createdAt;}
}
